Input: {"question": "Where is the Larkin Covered Bridge located?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d00", "start": 0, "end": 183, "text": "Larkin Covered Bridge (Chester Springs, Pennsylvania) Larkin Covered Bridge is a , Burr truss wooden covered bridge located in Chester Springs, Pennsylvania near the village of Eagle."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d00", "start": 184, "end": 321, "text": "The bridge, which originally crossed over Marsh Creek, now spans a dry ditch and is a feature of the Upper Uwchlan Township trail system."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d00", "start": 322, "end": 547, "text": "The original Larkin's Bridge was built in 1854 to span Marsh Creek, a tributary of the east branch of the Brandywine Creek, beside Jesse Larkin's Gristmill near the village of Milford Mills, southwest of its current location."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d00", "start": 548, "end": 579, "text": "The bridge was rebuilt in 1881."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d00", "start": 580, "end": 621, "text": "In 1972, the Commonwealth of Pennsylvania"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d01", "start": 0, "end": 175, "text": "Larkin Covered Bridge (Springfield, Massachusetts) Larkin Covered Bridge is a Burr truss wooden covered bridge located in Springfield, Massachusetts near the village of Eagle."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d01", "start": 176, "end": 313, "text": "The bridge, which originally crossed over Marsh Creek, now spans a dry ditch and is a feature of the Upper Uwchlan Township trail system."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d01", "start": 314, "end": 539, "text": "The original Larkin's Bridge was built in 1854 to span Marsh Creek, a tributary of the east branch of the Brandywine Creek, beside Jesse Larkin's Gristmill near the village of Milford Mills, southwest of its current location."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d01", "start": 540, "end": 571, "text": "The bridge was rebuilt in 1881."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d01", "start": 572, "end": 705, "text": "In 1972, the Commonwealth of Massachusetts took over the maintenance of the bridge, ensuring its preservation for future generations."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d02", "start": 0, "end": 193, "text": "Larkin Covered Bridge (North Tunbridge, Vermont) The Larkin Covered Bridge is a historic covered bridge, carrying Larkin Road across the First Branch White River in northern Tunbridge, Vermont."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d02", "start": 194, "end": 379, "text": "Built in 1902, it is one of the last documented covered bridges to be built in Vermont during the historic period of bridge construction, and is one of five covered bridges in the town."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d02", "start": 380, "end": 446, "text": "It was listed on the National Register of Historic Places in 1974."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d02", "start": 447, "end": 588, "text": "The Larkinn Covered Bridge stands a short way north of the village center of North Tunbridge, on Larkin Road a short way east of its junction"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d03", "start": 0, "end": 170, "text": "of the east branch of the Brandywine Creek , beside Jesse Larkin 's Gristmill near the village of Milford Mills , 2.5 miles ( 4.0 km ) southwest of its current location ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0284-0dbaae9d7fe3:d03", "start": 171, "end": 203, "text": "The bridge was rebuilt in 1881 ."},